from math import isqrt


def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    # A number's possible exponents are the divisors of the gcd of its
    # prime-factor exponents. Mobius inversion counts each perfect power once.
    limit = n.bit_length() - 1
    mu = [0] * (limit + 1)
    if limit >= 1:
        mu[1] = 1
    for divisor in range(1, limit + 1):
        for multiple in range(2 * divisor, limit + 1, divisor):
            mu[multiple] -= mu[divisor]

    def integer_root(exponent: int) -> int:
        if exponent == 2:
            return isqrt(n)
        low = 1
        high = 1 << ((n.bit_length() + exponent - 1) // exponent)
        while low + 1 < high:
            middle = (low + high) // 2
            if middle ** exponent <= n:
                low = middle
            else:
                high = middle
        return low

    # The base 1 contributes once and is excluded from all inversion terms.
    answer = 1
    for exponent in range(2, limit + 1):
        if mu[exponent]:
            answer -= mu[exponent] * (integer_root(exponent) - 1)
    return answer

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Every empty cell is a possible starting cell; reversing a path counts
    as a separate path.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if K >= len(cells):
        return 0

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def search(cell, remaining):
        if remaining == 0:
            return 1
        visited[cell] = True
        total = 0
        for neighbor in neighbors[cell]:
            if not visited[neighbor]:
                total += search(neighbor, remaining - 1)
        visited[cell] = False
        return total

    return sum(search(start, K) for start in range(len(cells)))

from functools import lru_cache
from math import gcd


# Every possible nonzero digit sum is at most 81. Products of
# nonzero digits have only the prime factors 2, 3, 5, and 7.
_PRODUCT_MODULUS = 64 * 81 * 25 * 49


@lru_cache(maxsize=None)
def _bad_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count zero-free completions whose product fails divisibility."""
    if remaining == 0:
        return int(digit_sum > 0 and product % digit_sum != 0)
    return sum(
        _bad_suffix(
            remaining - 1,
            digit_sum + digit,
            gcd(product * digit, _PRODUCT_MODULUS),
        )
        for digit in range(1, 10)
    )


@lru_cache(maxsize=None)
def _beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = [int(char) for char in str(bound)]
    bad = sum(_bad_suffix(length, 0, 1) for length in range(1, len(digits)))
    digit_sum, product = 0, 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(1, limit):
            bad += _bad_suffix(
                remaining,
                digit_sum + digit,
                gcd(product * digit, _PRODUCT_MODULUS),
            )
        if limit == 0:
            # All numbers matching this prefix contain a zero, so are beautiful.
            break
        digit_sum += limit
        product = gcd(product * limit, _PRODUCT_MODULUS)
    else:
        bad += int(product % digit_sum != 0)

    # Numbers containing a zero have product zero and positive digit sum.
    return bound - bad


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers in [l, r] whose digit product is divisible by their sum.

    Args:
        l: Inclusive lower bound.
        r: Inclusive upper bound.

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _beautiful_up_to(r) - _beautiful_up_to(l - 1)

