from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination.

    Denominations cannot be combined. The input contains 1-15 positive
    denominations (normally at most 25), and k is between 1 and 2*10**9.
    """
    # Multiples of a denomination divisible by a smaller one add no amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    upper = denominations[0] * k
    # Coefficients collect all inclusion-exclusion subsets sharing an LCM.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for divisor, coefficient in coefficients.items():
            common = divisor // gcd(divisor, coin) * coin
            if common <= upper:
                additions[common] = additions.get(common, 0) - coefficient
        for divisor, coefficient in additions.items():
            coefficients[divisor] = coefficients.get(divisor, 0) + coefficient
            if coefficients[divisor] == 0:
                del coefficients[divisor]

    lower = 1
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in coefficients.items())
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower

